window.AUTH=window.AUTH||{};window.AUTH["18-389"]={"d":"18-389","id":"2018/18-389","n":"Parker Drilling Management Services, Ltd. v. Newton","briefs":[{"k":"petitioner","label":"Brief of petitioner Parker Drilling Management Services, Ltd.","date":"2019-02-20","url":"https://www.supremecourt.gov/DocketPDF/18/18-389/88946/20190220140705064_18-389%20ts%20--%20PDFA.pdf","side":"pet","n":70},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2019-02-27","url":"https://www.supremecourt.gov/DocketPDF/18/18-389/90005/20190227191225843_18-389tsacUnitedStates.pdf","side":"us","n":63},{"k":"respondent","label":"Brief of respondent Brian Newton","date":"2019-03-22","url":"https://www.supremecourt.gov/DocketPDF/18/18-389/92947/20190322163002275_18-389bs.pdf","side":"res","n":71},{"k":"reply","label":"Reply of petitioner Parker Drilling Management Services, Ltd.","date":"2019-04-09","url":"https://www.supremecourt.gov/DocketPDF/18/18-389/95772/20190409134829125_00000001.pdf","side":"pet","n":25}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/18-389_4g15.pdf","tr":true,"items":[{"t":"case","label":"Allison v. Boeing Laser Tech. Servs.","cite":"689 F.3d 1234","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/689/1234/","by":{"0":"21, 45","3":"10"}},{"t":"case","label":"Amber Res. Co. v. United States","cite":"538 F.3d 1358","y":2008,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/538/1358/","by":{"0":"4"}},{"t":"case","label":"Bailey v. United States","cite":"516 U.S. 137","y":1995,"id":"1995/94-7448","sc":1,"sum":"The proximity and accessibility test for \"use\" is so broad that no independent role remains for \"carry.\" \"Use\" in Section 924(c)(1) requires more than proximity and accessibility that might embolden a defendant. It requires active employment of the firearm by the defendant, making the firearm an operative factor in relation to the predicate offense.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Barrentine v. Arkansas-Best Freight Sys., Inc.","cite":"450 U.S. 728","y":1981,"id":"1980/79-2006","sc":1,"sum":"Petitioners' wage claims under the FLSA are not barred by the prior submission of their grievances to the contractual dispute-resolution procedures.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7, 8, 30","2":"29, 32"}},{"t":"case","label":"Brigham v. Eugene Water & Elec. Bd.","cite":"357 F.3d 931","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/357/931/","by":{"0":"9"}},{"t":"case","label":"Brock v. Cincinnati","cite":"236 F.3d 793","y":2001,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/236/793/","sum":"Noting that an agreement is reasonable if it “falls within a broad zone of reasonableness, considering its terms and all of the facts and circumstances of the parties’ relationship”.","sumSrc":"brief:0","by":{"0":"9"}},{"t":"case","label":"Chevron Oil Co. v. Huson","cite":"404 U.S. 97","y":1971,"id":"1971/70-11","sc":1,"op":2,"sum":"The Supreme Court held that Louisiana's statute of limitations was applicable under the Outer Continental Shelf Lands Act because the Lands Act specifically adopted relevant state laws as federal laws. There was no federal statute of limitations specified in the Lands Act so, state law was not inconsistent.","sumSrc":"Oyez","by":{"0":"26, 27","1":"10, 17, 20","2":"7, 8, 19, 20, 25, 26, 32, 37, 43, 44, 52","3":"12"}},{"t":"case","label":"Chi., Rock Island & Pac. Ry. Co. v. McGlinn","cite":"114 U.S. 542","y":1885,"id":"scdb/1884-233","sc":1,"op":1,"sum":"Fort Leavenworth v. Lowe, ante, 525, affirmed and applied to this case.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"20, 34, 35","1":"12, 13, 23","2":"40","3":"7, 8"}},{"t":"case","label":"Christopher v. SmithKline Beecham","cite":"567 U.S. 142","y":2012,"id":"2011/11-204","sc":1,"sum":"The Court held that the Secretary of Labor's definition of \"outside salesman\" apply to pharmaceutical sales representatives under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"0":"50","3":"13"}},{"t":"case","label":"Cont’l Oil Co. v. London S.S. Owners’ Mut. Ins. Ass’n","cite":"417 F.2d 1030","y":1969,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/417/1030/","op":2,"by":{"0":"passim","1":"passim","2":"14, 41, 42","3":"12"}},{"t":"case","label":"Cosme Nieves v. Deshler","cite":"786 F.2d 455","y":1986,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/786/455/","by":{"0":"43"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"138 S. Ct. 1134","y":2018,"id":"2017/16-1362","sc":1,"sum":"The Court decided that because service advisors at car dealerships are “salesm[e]n . . . primarily engaged in . . . servicing automobiles,” 29 U.S.C. § 213(b)(10)(A), they are exempt from the Fair Labor Standards Act's overtime-pay requirements.","sumSrc":"Oyez","by":{"0":"47, 50"}},{"t":"case","label":"Faragher v. City of Boca Raton","cite":"524 U.S. 775","y":1998,"id":"1997/97-282","sc":1,"sum":"The Court held that an employer is vicariously liable under Title VII of the Civil Rights Act of 1964 for actionable discrimination caused by a supervisor.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Genesis Healthcare Corp. v. Symczyk","cite":"569 U.S. 66","y":2013,"id":"2012/11-1059","sc":1,"sum":"The Court held that a collective action suit on behalf of other \"similarly situated\" employees becomes moot when the individual claim does.","sumSrc":"Oyez","by":{"0":"32","1":"22"}},{"t":"case","label":"Goodyear Atomic Corp. v. Miller","cite":"486 U.S. 174","y":1988,"id":"1987/86-1172","sc":1,"sum":"Appellee Miller, an employee of appellant at an Ohio nuclear production facility owned by the United States but operated by appellant, a private contractor, received a workers' compensation award from appellee Ohio Industrial Commission (Commission) for injuries sustained in a fall allegedly caused by a bolt protruding from the scaffold on which he was working. On the basis of a state safety regulation prohibiting …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Gregory v. Ashcroft","cite":"501 U.S. 452","y":1991,"id":"1990/90-50","sc":1,"sum":"In addition to emphasizing Missouri's, or any other state's, Tenth Amendment right to define the qualifications of its highest state officials, the Court held that the regulations of the ADEA did not apply to \"policy-making\" appointees such as state court judges.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Gulf Offshore Co. v. Mobil Oil Corp.","cite":"453 U.S. 473","y":1981,"id":"1980/80-590","sc":1,"op":1,"sum":"Respondent Mobil Oil Corp. contracted with petitioner for the latter's performance of certain operations on offshore oil drilling platforms. Under the agreement, petitioner promised to indemnify Mobil for all claims resulting directly or indirectly from the work. One of petitioner's employees (also a respondent), working on an oil drilling platform above the seabed of the Outer Continental Shelf, was injured while, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7, 27","1":"10, 11, 14, 17, 18","2":"26, 27, 28, 32, 53","3":"12"}},{"t":"case","label":"Indus. Welfare Comm’n v. Superior Court","cite":"613 P.2d 579","y":1980,"court":"Cal.","url":"https://www.courtlistener.com/c/P.2d/613/579/","by":{"0":"10"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"sum":"The §243(h) \"clear probability\" standard of proof does not govern asylum applications under §208(a).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45","1":"30"}},{"t":"case","label":"Integrity Staffing Sols. v. Busk","cite":"135 S. Ct. 513","y":2014,"id":"2014/13-433","sc":1,"sum":"The Court ruled that employees of Integrity Staffing Solutions, Inc. could not be compensated for time spent passing through security checkpoints, because the checkpoints were not integral to their principal duties as employees.","sumSrc":"Oyez","by":{"0":"50"}},{"t":"case","label":"James Stewart & Co. v. Sadrakula","cite":"309 U.S. 94","y":1940,"id":"scdb/1939-058","sc":1,"op":4,"sum":"that the intention was to relieve the contractor from provisions of the city building code relating to types of material, fire hazards and the like. P. 105. 254 App. Div. 892; 5 N. Y. S. 2d 260, affirmed. APPEAL from a judgment of the Supreme Court of New York, entered on remittitur from the Court of Appeals, 280 N. Y. 651, 730; 20 N. E. 2d 1015; 21 N. E. 2d 217, and sustaining an award of damages for accidental …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35","2":"6-7, 38, 39, 40","3":"9"}},{"t":"case","label":"Judulang v. Holder","cite":"565 U.S. 42","y":2011,"id":"2011/10-694","sc":1,"sum":"The Court held that the policy used to determine whether a resident alien is able to ask for relief from deportation under a repealed portion of immigration laws is “arbitrary and capricious” under the Administrative Procedure Act, 5 U.S.C. § 706(2)(A).","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Koren v. Martin Marietta Servs., Inc.","cite":"997 F. Supp. 196","y":1998,"court":"D.P.R.","url":"https://www.courtlistener.com/c/F.%20Supp./997/196/","by":{"0":"7"}},{"t":"case","label":"LeSassier v. Chevron USA, Inc.","cite":"776 F.2d 506","y":1985,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/776/506/","by":{"0":"28","1":"19"}},{"t":"case","label":"Lewis v. United States","cite":"523 U.S. 155","y":1998,"id":"1997/96-7151","sc":1,"op":1,"sum":"The Court held that, because the ACA does not make Louisiana's first-degree murder statute part of federal law, the federal second-degree murder statute governs Lewis' crime.","sumSrc":"Oyez","by":{"0":"46","1":"passim","2":"35, 51"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"op":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"0":"38","3":"3"}},{"t":"case","label":"McQuiggin v. Perkins","cite":"569 U.S. 383","y":2013,"id":"2012/12-126","sc":1,"op":1,"sum":"The Court held that proving actual innocence allows a petitioner to pursue habeas corpus relief regardless of a statute of limitations.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Mendiola v. CPS Sec. Sols., Inc.","cite":"340 P.3d 355","y":2015,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/340/355/","op":1,"ar":1,"sum":"Noting “whether on-call time constitutes hours worked . . . focuse[s] on the extent of the employer’s control” and citing multiple factors, many from federal law, for determining control.","sumSrc":"brief:2","by":{"0":"passim","1":"27, 31","2":"47"}},{"t":"case","label":"Moody v. Callon Petroleum Operating Co.","cite":"37 F. Supp. 2d 805","y":1999,"court":"E.D. La.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/37/805/","by":{"0":"28"}},{"t":"case","label":"Nations v. Morris","cite":"483 F.2d 577","y":1973,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/483/577/","by":{"0":"28","1":"19"}},{"t":"case","label":"Paul v. United States","cite":"371 U.S. 245","y":1963,"id":"1962/19","sc":1,"op":3,"ar":1,"sum":"California attempted to enforce her minimum wholesale price regulations with respect to milk sold to the United States at three military installations in the State. Such milk was purchased for strictly military consumption, for resale at federal commissaries, for use at various military clubs or for resale in various post exchanges. The United States sued in a Federal District Court to enjoin enforcement of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21","1":"12, 23","2":"7, 39, 40","3":"9"}},{"t":"case","label":"Powell v. U.S. Cartridge Co.","cite":"339 U.S. 497","y":1950,"id":"scdb/1949-075","sc":1,"ar":5,"sum":"The Fair Labor Standards. Act applies to employees of a private contractor operating a Government-owned munitions plant under a cost-plus-a-fixed-fee contract with the Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7, 30","1":"27","2":"12, 17, 20, 31, 32, 46, 49","3":"16, 18"}},{"t":"case","label":"Pure Oil Co. v. Snipes","cite":"293 F.2d 60","y":1961,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/293/60/","by":{"0":"44"}},{"t":"case","label":"Ransom v. FIA Card Services","cite":"562 U.S. 61","y":2011,"id":"2010/09-907","sc":1,"op":1,"sum":"The Court held that a debtor who does not make a loan or lease payment could not take the car-ownership deduction.","sumSrc":"Oyez","by":{"0":"35, 36, 38","1":"11, 13","2":"36"}},{"t":"case","label":"Rodrigue v. Aetna Cas. & Sur. Co.","cite":"395 U.S. 352","y":1969,"id":"1968/436","sc":1,"op":5,"ar":1,"sum":"Petitioners' remedy is under the Lands Act and Louisiana law. Under the Lands Act, federal law, supplemented by the law of the adjacent State not inconsistent with federal law, is to be applied to artificial islands, which Congress clearly intended were to be treated as islands or federal enclaves within a landlocked State and not as vessels subject to admiralty jurisdiction: Pp. 355-366. 391 F. 2d 671 and 395 F. 2d …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"passim","2":"7, 24, 25, 43","3":"passim"}},{"t":"case","label":"Rousseau v. Teledyne Movible Offshore, Inc.","cite":"805 F.2d 1245","y":1986,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/805/1245/","sum":"Holding off-duty hours noncompensable for employees residing on employer’s barges.","sumSrc":"brief:0","by":{"0":"9"}},{"t":"case","label":"Shell Oil Co. v. Iowa Dep’t of Revenue","cite":"488 U.S. 19","y":1988,"id":"1988/87-984","sc":1,"op":2,"sum":"The OCSLA does not prevent Iowa from including income earned from the sale of OCS oil and gas in its apportionment formula. In adopting for the OCS the civil and criminal laws of \"each adjacent state,\" the OCSLA does provide that \"[s]tate taxation laws shall not apply\" and further specifies that such adoption \"shall never be interpreted as a basis for [a State's] claiming any interest in [the OCS] or the revenues …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 43","1":"2, 11, 13","2":"4, 5, 6","3":"4"}},{"t":"case","label":"Skidmore v. Swift & Co.","cite":"323 U.S. 134","y":1944,"id":"1940-1955/12","sc":1,"sum":"The Court held that there was no reason that time spent waiting could not also be time spent working, especially in cases in which the conditions of employment involve waiting time. Although it can be difficult to determine the facts of a case and whether the activity in question constitutes work, Congress granted the courts the authority to do so.","sumSrc":"Oyez","by":{"0":"8"}},{"t":"case","label":"Sturgeon v. Frost","cite":"136 S. Ct. 1061","y":2016,"id":"2015/14-1209","sc":1,"sum":"The Court held that the Alaska National Interest Lands Conservation Act of 1980 did not allow the National Park Service to regulate all land physically within the boundaries of the National Park System in Alaska.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Tenn. Coal, Iron & R.R. Co. v. Muscoda Local No. 123","cite":"321 U.S. 590","y":1944,"id":"scdb/1943-089","sc":1,"sum":"1. The Fair Labor Standards Act is remedial and humanitarian in nature and must not be interpreted or applied in a narrow, grudging manner.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8","2":"32"}},{"t":"case","label":"United States v. California","cite":"332 U.S. 19","y":1947,"id":"scdb/1946-143","sc":1,"op":1,"by":{"0":"4","1":"2","2":"3, 4"}},{"t":"case","label":"United States v. Darby","cite":"312 U.S. 100","y":1941,"id":"1940-1955/312us100","sc":1,"sum":"The Court held that the Fair Labor Standards Act complied with the Commerce Clause, giving Congress the ability to regulate interstate commerce.","sumSrc":"Oyez","by":{"0":"7, 30","1":"22"}},{"t":"case","label":"United States v. Louisiana","cite":"339 U.S. 699","y":1950,"id":"scdb/1949-113","sc":1,"op":1,"ar":2,"sum":"1. In this suit, brought in this Court by the United States against the State of Louisiana under Art. III, § 2, Cl. 2 of the Constitution, held: The United States is entitled to a decree adjudging and declaring the paramount rights of the United States as against Louisiana in the area claimed by Louisiana which lies under the Gulf of Mexico beyond the low-water mark on the coast of Louisiana and outside of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5","1":"2","2":"3, 4"}},{"t":"case","label":"United States v. Maine","cite":"420 U.S. 515","y":1975,"id":"1974/35_orig","sc":1,"op":1,"sum":"The United States, to the exclusion of defendant Atlantic Coastal States, held to have sovereign rights over the seabed and subsoil underlying the Atlantic Ocean, lying more than three geographical miles seaward from the ordinary low-water mark and from the outer limits of inland coastal waters, extending seaward to the outer edge of the Continental Shelf, that area, like the seabed adjacent to the coastline, being …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46","1":"3, 10, 32","2":"5"}},{"t":"case","label":"United States v. Sharpnack","cite":"355 U.S. 286","y":1958,"id":"1957/35","sc":1,"op":1,"sum":"The Assimilative Crimes Act of 1948, 18 U. S. C. § 13, is constitutional insofar as it makes applicable to a federal enclave a subsequently enacted criminal law of the State in which the enclave is situated. Pp. 286-297. Reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29","1":"13, 14","2":"9","3":"9, 10"}},{"t":"case","label":"United States v. Texas","cite":"339 U.S. 707","y":1950,"id":"scdb/1949-114","sc":1,"op":1,"sum":"1. In this suit, brought in this Court by the United States against the State of Texas under Art. III, § 2, Cl. 2 of the Constitution, held: The United States is entitled to a decree adjudging and declaring the. paramount rights of the United States as against Texas in the area claimed by Texas which lies under the Gulf of Mexico beyond the low-water mark on the coast of Texas and outside the inland waters, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5","1":"2","2":"3, 4"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Williams v. Brinderson Constructors, Inc.","cite":"2015 WL 4747892","y":2015,"court":"C.D. Cal. Aug. 11","by":{"0":"28"}},{"t":"const","label":"Article I, Section 8, Clause 17","text":"To exercise exclusive Legislation in all Cases whatsoever, over such District (not exceeding ten Miles square) as may, by Cession of particular States, and the Acceptance of Congress, become the Seat of the Government of the United States, and to exercise like Authority over all Places purchased by the Consent of the Legislature of the State in which the Same shall be, for the Erection of Forts, Magazines, Arsenals, dock-Yards, and other needful Buildings;—And","by":{"0":"21"}},{"t":"usc","label":"10 U.S.C. § 2671","url":"https://www.law.cornell.edu/uscode/text/10/2671","subs":["(a)"],"by":{"0":"21"}},{"t":"usc","label":"11 U.S.C. § 707","url":"https://www.law.cornell.edu/uscode/text/11/707","subs":["(b)(2)(A)(ii)(I)"],"by":{"0":"35"}},{"t":"usc","label":"26 U.S.C. § 3305","url":"https://www.law.cornell.edu/uscode/text/26/3305","subs":["(d)"],"by":{"0":"21"}},{"t":"usc","label":"28 U.S.C. § 5001","url":"https://www.law.cornell.edu/uscode/text/28/5001","subs":["(a)"],"by":{"0":"21"}},{"t":"usc","label":"29 U.S.C. § 207","url":"https://www.law.cornell.edu/uscode/text/29/207","subs":["(a)","(a)(1)"],"stext":{"head":"§207. Maximum hours","paras":[[0,"(a) Employees engaged in interstate commerce; additional applicability to employees pursuant to subsequent amendatory provisions"],[0,"(1) Except as otherwise provided in this section, no employer shall employ any of his employees who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, for a workweek longer than forty hours unless such employee receives compensation for his employment in excess of the hours above specified at a rate not less than one and one-half times the regular rate at which he is employed."],[0,"(2) No employer shall employ any of his employees who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, and who in such workweek is brought within the purview of this subsection by the amendments made to this chapter by the Fair Labor Standards Amendments of 1966—"],[1,"(A) for a workweek longer than forty-four hours during the first year from the effective date of the Fair Labor Standards Amendments of 1966,"],[1,"(B) for a workweek longer than forty-two hours during the second year from such date, or"],[1,"(C) for a workweek longer than forty hours after the expiration of the second year from such date,"],[0,"unless such employee receives compensation for his employment in excess of the hours above specified at a rate not less than one and one-half times the regular rate at which he is employed."],[0,"(b) Employment pursuant to collective bargaining agreement; employment by independently owned and controlled local enterprise engaged in distribution of petroleum products"],[0,"No employer shall be deemed to have violated subsection (a) by employing any employee for a workweek in excess of that specified in such subsection without paying the compensation for overtime employment prescribed therein if such employee is so employed—"],[1,"(1) in pursuance of an agreement, made as a result of collective bargaining by representatives of employees certified as bona fide by the National Labor Relations Board, which provides that no employee shall be employed more than one thousand and forty hours during any period of twenty-six consecutive weeks; or"],[1,"(2) in pursuance of an agreement, made as a result of collective bargaining by representatives of employees certified as bona fide by the National Labor Relations Board, which provides that during a specified period of fifty-two consecutive weeks the employee shall be employed not more than two thousand two hundred and forty hours and shall be guaranteed not less than one thousand eight hundred and forty-hours (or not less than forty-six weeks at the normal number of hours worked per week, but not less than thirty hours per week) and not more than two thousand and eighty hours of employment for which he shall receive compensation for all hours guaranteed or worked at rates not less than those applicable under the agreement to the work performed and for all hours in excess of the guaranty which are also in excess of the maximum workweek applicable to such employee under subsection (a) or two thousand and eighty in such period at rates not less than one and one-half times the regular rate at which he is employed; or"],[1,"(3) by an independently owned and controlled local enterprise (including an enterprise with more than one bulk storage establishment) engaged in the wholesale or bulk distribution of petroleum products if—"],[2,"(A) the annual gross volume of sales of such enterprise is less than $1,000,000 exclusive of excise taxes,"],[2,"(B) more than 75 per centum of such enterprise's annual dollar volume of sales is made within the State in which such enterprise is located, and"],[2,"(C) not more than 25 per centum of the annual dollar volume of sales of such enterprise is to customers who are engaged in the bulk distribution of such products for resale,"],[1,"and such employee receives compensation for employment in excess of forty hours in any workweek at a rate not less than one and one-half times the minimum wage rate applicable to him under section 206 of this title,"],[0,"and if such employee receives compensation for employment in excess of twelve hours in any workday, or for employment in excess of fifty-six hours in any workweek, as the case may be, at a rate not less than one and one-half times the regular rate at which he is employed."],[0,"(c), (d) Repealed. Pub. L. 93–259, §19(e), Apr. 8, 1974, 88 Stat. 66"],[0,"(e) \"Regular rate\" defined"],[0,"As used in this section the \"regular rate\" at which an employee is employed shall be deemed to include all remuneration for employment paid to, or on behalf of, the employee, but shall not be deemed to include—"],[1,"(1) sums paid as gifts; payments in the nature of gifts made at Christmas time or on other special occasions, as a reward for service, the amounts of which are not measured by or dependent on hours worked, production, or efficiency;"],[1,"(2) payments made for occasional periods when no work is performed due to vacation, holiday, illness, failure of the employer to provide sufficient work, or other similar cause; reasonable payments for traveling expenses, or other expenses, incurred by an employee in the furtherance of his employer's interests and properly reimbursable by the employer; and other similar payments to an employee which are not made as compensation for his hours of employment;"],[1,"(3) Sums 1 paid in recognition of services performed during a given period if either, (a) both the fact that payment is to be made and the amount of the payment are determined at the sole discretion of the employer at or near the end of the period and not pursuant to any prior contract, agreement, or promise causing the employee to expect such payments regularly; or (b) the payments are made pursuant to a bona fide profit-sharing plan or trust or bona fide thrift or savings plan, meeting the requirements of the Administrator set forth in appropriate regulations which he shall issue, having due regard among other relevant factors, to the extent to which the amounts paid to the employee are determined without regard to hours of work, production, or efficiency; or (c) the payments are talent fees (as such talent fees are defined and delimited by regulations of the Administrator) paid to performers, including announcers, on radio and television programs;"],[1,"(4) contributions irrevocably made by an employer to a trustee or third person pursuant to a bona fide plan for providing old-age, retirement, life, accident, or health insurance or similar benefits for employees;"],[1,"(5) extra compensation provided by a premium rate paid for certain hours worked by the employee in any day or workweek because such hours are hours worked in excess of eight in a day or in excess of the maximum workweek applicable to such employee under subsection (a) or in excess of the employee's normal working hours or regular working hours, as the case may be;"],[1,"(6) extra compensation provided by a premium rate paid for work by the employee on Saturdays, Sundays, holidays, or regular days of rest, or on the sixth or seventh day of the workweek, where such premium rate is not less than one and one-half times the rate established in good faith for like work performed in nonovertime hours on other days;"],[1,"(7) extra compensation provided by a premium rate paid to the employee, in pursuance of an applicable employment contract or collective-bargaining agreement, for work outside of the hours established in good faith by the contract or agreement as the basic, normal, or regular workday (not exceeding eight hours) or workweek (not exceeding the maximum workweek applicable to such employee under subsection (a),2 where such premium rate is not less than one and one-half times the rate established in good faith by the contract or agreement for like work performed during such workday or workweek; or"],[1,"(8) any value or income derived from employer-provided grants or rights provided pursuant to a stock option, stock appreciation right, or bona fide employee stock purchase program which is not otherwise excludable under any of paragraphs (1) through (7) if—"],[2,"(A) grants are made pursuant to a program, the terms and conditions of which are communicated to participating employees either at the beginning of the employee's participation in the program or at the time of the grant;"],[2,"(B) in the case of stock options and stock appreciation rights, the grant or right cannot be exercisable for a period of at least 6 months after the time of grant (except that grants or rights may become exercisable because of an employee's death, disability, retirement, or a change in corporate ownership, or other circumstances permitted by regulation), and the exercise price is at least 85 percent of the fair market value of the stock at the time of grant;"],[2,"(C) exercise of any grant or right is voluntary; and"],[2,"(D) any determinations regarding the award of, and the amount of, employer-provided grants or rights that are based on performance are—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/207?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§207. Maximum hours","tname":"Labor","by":{"0":"8","1":"31"}},{"t":"usc","label":"29 U.S.C. § 211","url":"https://www.law.cornell.edu/uscode/text/29/211","subs":["(c)"],"by":{"0":"32"}},{"t":"usc","label":"29 U.S.C. § 216","url":"https://www.law.cornell.edu/uscode/text/29/216","subs":["(b)"],"by":{"0":"32"}},{"t":"usc","label":"29 U.S.C. § 218","url":"https://www.law.cornell.edu/uscode/text/29/218","subs":["(a)"],"stext":{"head":"§218. Relation to other laws","paras":[[0,"(a) No provision of this chapter or of any order thereunder shall excuse noncompliance with any Federal or State law or municipal ordinance establishing a minimum wage higher than the minimum wage established under this chapter or a maximum work week lower than the maximum workweek established under this chapter, and no provision of this chapter relating to the employment of child labor shall justify noncompliance with any Federal or State law or municipal ordinance establishing a higher standard than the standard established under this chapter. No provision of this chapter shall justify any employer in reducing a wage paid by him which is in excess of the applicable minimum wage under this chapter, or justify any employer in increasing hours of employment maintained by him which are shorter than the maximum hours applicable under this chapter."],[0,"(b) Notwithstanding any other provision of this chapter (other than section 213(f) of this title) or any other law—"],[1,"(1) any Federal employee in the Canal Zone engaged in employment of the kind described in section 5102(c)(7) of title 5, or"],[1,"(2) any employee employed in a nonappropriated fund instrumentality under the jurisdiction of the Armed Forces,"],[0,"shall have his basic compensation fixed or adjusted at a wage rate that is not less than the appropriate wage rate provided for in section 206(a)(1) of this title (except that the wage rate provided for in section 206(b) of this title shall apply to any employee who performed services during the workweek in a work place within the Canal Zone), and shall have his overtime compensation set at an hourly rate not less than the overtime rate provided for in section 207(a)(1) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/218?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§218. Relation to other laws","tname":"Labor","by":{"0":"13, 17, 42","1":"31"}},{"t":"usc","label":"40 U.S.C. § 3172","url":"https://www.law.cornell.edu/uscode/text/40/3172","subs":["(a)"],"by":{"0":"21"}},{"t":"usc","label":"42 U.S.C. § 7418","url":"https://www.law.cornell.edu/uscode/text/42/7418","subs":["(a)"],"stext":{"head":"§7418. Control of pollution from Federal facilities","paras":[[0,"(a) General compliance"],[0,"Each department, agency, and instrumentality of the executive, legislative, and judicial branches of the Federal Government (1) having jurisdiction over any property or facility, or (2) engaged in any activity resulting, or which may result, in the discharge of air pollutants, and each officer, agent, or employee thereof, shall be subject to, and comply with, all Federal, State, interstate, and local requirements, administrative authority, and process and sanctions respecting the control and abatement of air pollution in the same manner, and to the same extent as any nongovernmental entity. The preceding sentence shall apply (A) to any requirement whether substantive or procedural (including any recordkeeping or reporting requirement, any requirement respecting permits and any other requirement whatsoever), (B) to any requirement to pay a fee or charge imposed by any State or local agency to defray the costs of its air pollution regulatory program, (C) to the exercise of any Federal, State, or local administrative authority, and (D) to any process and sanction, whether enforced in Federal, State, or local courts, or in any other manner. This subsection shall apply notwithstanding any immunity of such agencies, officers, agents, or employees under any law or rule of law. No officer, agent, or employee of the United States shall be personally liable for any civil penalty for which he is not otherwise liable."],[0,"(b) Exemption"],[0,"The President may exempt any emission source of any department, agency, or instrumentality in the executive branch from compliance with such a requirement if he determines it to be in the paramount interest of the United States to do so, except that no exemption may be granted from section 7411 of this title, and an exemption from section 7412 of this title may be granted only in accordance with section 7412(i)(4) of this title. No such exemption shall be granted due to lack of appropriation unless the President shall have specifically requested such appropriation as a part of the budgetary process and the Congress shall have failed to make available such requested appropriation. Any exemption shall be for a period not in excess of one year, but additional exemptions may be granted for periods of not to exceed one year upon the President's making a new determination. In addition to any such exemption of a particular emission source, the President may, if he determines it to be in the paramount interest of the United States to do so, issue regulations exempting from compliance with the requirements of this section any weaponry, equipment, aircraft, vehicles, or other classes or categories of property which are owned or operated by the Armed Forces of the United States (including the Coast Guard) or by the National Guard of any State and which are uniquely military in nature. The President shall reconsider the need for such regulations at three-year intervals. The President shall report each January to the Congress all exemptions from the requirements of this section granted during the preceding calendar year, together with his reason for granting each such exemption."],[0,"(c) Government vehicles"],[0,"Each department, agency, and instrumentality of executive, legislative, and judicial branches of the Federal Government shall comply with all applicable provisions of a valid inspection and maintenance program established under the provisions of subpart 2 of part D or subpart 3 of part D except for such vehicles that are considered military tactical vehicles."],[0,"(d) Vehicles operated on Federal installations"],[0,"Each department, agency, and instrumentality of executive, legislative, and judicial branches of the Federal Government having jurisdiction over any property or facility shall require all employees which operate motor vehicles on the property or facility to furnish proof of compliance with the applicable requirements of any vehicle inspection and maintenance program established under the provisions of subpart 2 of part D or subpart 3 of part D for the State in which such property or facility is located (without regard to whether such vehicles are registered in the State). The installation shall use one of the following methods to establish proof of compliance—"],[1,"(1) presentation by the vehicle owner of a valid certificate of compliance from the vehicle inspection and maintenance program;"],[1,"(2) presentation by the vehicle owner of proof of vehicle registration within the geographic area covered by the vehicle inspection and maintenance program (except for any program whose enforcement mechanism is not through the denial of vehicle registration);"],[1,"(3) another method approved by the vehicle inspection and maintenance program administrator."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7418?type=usc&year=mostrecent&link-type=html"},"head":"§7418. Control of pollution from Federal facilities","tname":"The Public Health and Welfare","by":{"0":"21","2":"54"}},{"t":"usc","label":"43 U.S.C. § 1301-15","url":"https://www.law.cornell.edu/uscode/text/43/1301-15","subs":["(1953)"],"by":{"0":"4"}},{"t":"usc","label":"43 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/43/1331","subs":["(a)"],"stext":{"head":"§1331. Definitions","paras":[[0,"In this subchapter:"],[0,"(a) Outer Continental Shelf.—The term \"outer Continental Shelf\" means—"],[1,"(1) all submerged lands lying seaward and outside of the area of lands beneath navigable waters as defined in section 1301 of this title, and of which the subsoil and seabed appertain to the United States and are subject to its jurisdiction and control or within the exclusive economic zone of the United States and adjacent to any territory of the United States; and"],[1,"(2) does not include any area conveyed by Congress to a territorial government for administration;"],[0,"(b) Secretary.—The term \"Secretary\" means the Secretary of the Interior, except that with respect to functions under this subchapter transferred to, or vested in, the Secretary of Energy or the Federal Energy Regulatory Commission by or pursuant to the Department of Energy Organization Act (42 U.S.C. 7101 et seq.), the term \"Secretary\" means the Secretary of Energy, or the Federal Energy Regulatory Commission, as the case may be."],[0,"(c) Lease.—The term \"lease\" means any form of authorization which is issued under section 1337 of this title or maintained under section 1335 of this title and which authorizes exploration for, and development and production of, minerals."],[0,"(d) Person.—The term \"person\" includes, in addition to a natural person, an association, a State, a political subdivision of a State, or a private, public, or municipal corporation."],[0,"(e) Coastal zone.—The term \"coastal zone\" means the coastal waters (including the lands therein and thereunder) and the adjacent shorelands (including the waters therein and thereunder), strongly influenced by each other and in proximity to the shorelines of the several coastal States, and includes islands, transition and intertidal areas, salt marshes, wetlands, and beaches, which zone extends seaward to the outer limit of the United States territorial sea and extends inland from the shorelines to the extent necessary to control shorelands, the uses of which have a direct and significant impact on the coastal waters, and the inward boundaries of which may be identified by the several coastal States, pursuant to the authority of section 1454(b)(1) 1 of title 16."],[0,"(f) Affected State.—The term \"affected State\" means, with respect to any program, plan, lease sale, or other activity, proposed, conducted, or approved pursuant to the provisions of this subchapter, any State—"],[1,"(1) the laws of which are declared, pursuant to section 1333(a)(2) of this title, to be the law of the United States for the portion of the outer Continental Shelf on which such activity is, or is proposed to be, conducted;"],[1,"(2) which is, or is proposed to be, directly connected by transportation facilities to any artificial island or structure referred to in section 1333(a)(1) of this title;"],[1,"(3) which is receiving, or in accordnace 2 with the proposed activity will receive, oil for processing, refining, or transshipment which was extracted from the outer Continental Shelf and transported directly to such State by means of vessels or by a combination of means including vessels;"],[1,"(4) which is designated by the Secretary as a State in which there is a substantial probability of significant impact on or damage to the coastal, marine, or human environment, or a State in which there will be significant changes in the social, governmental, or economic infrastructure, resulting from the exploration, development, and production of oil and gas anywhere on the outer Continental Shelf; or"],[1,"(5) in which the Secretary finds that because of such activity there is, or will be, a significant risk of serious damage, due to factors such as prevailing winds and currents, to the marine or coastal environment in the event of any oilspill, blowout, or release of oil or gas from vessels, pipelines, or other transshipment facilities."],[0,"(g) Marine environment.—The term \"marine environment\" means the physical, atmospheric, and biological components, conditions, and factors which interactively determine the productivity, state, condition, and quality of the marine ecosystem, including the waters of the high seas, the contiguous zone, transitional and intertidal areas, salt marshes, and wetlands within the coastal zone and on the outer Continental Shelf."],[0,"(h) Coastal environment.—The term \"coastal environment\" means the physical atmospheric, and biological components, conditions, and factors which interactively determine the productivity, state, condition, and quality of the terrestrial ecosystem from the shoreline inward to the boundaries of the coastal zone."],[0,"(i) Human environment.—The term \"human environment\" means the physical, social, and economic components, conditions, and factors which interactively determine the state, condition, and quality of living conditions, employment, and health of those affected, directly or indirectly, by activities occurring on the outer Continental Shelf."],[0,"(j) Governor.—The term \"Governor\" means the Governor of a State, or the person or entity designated by, or pursuant to, State law to exercise the powers granted to such Governor pursuant to this subchapter."],[0,"(k) Exploration.—The term \"exploration\" means the process of searching for minerals, including (1) geophysical surveys where magnetic, gravity, seismic, or other systems are used to detect or imply the presence of such minerals, and (2) any drilling, whether on or off known geological structures, including the drilling of a well in which a discovery of oil or natural gas in paying quantities is made and the drilling of any additional delineation well after such discovery which is needed to delineate any reservoir and to enable the lessee to determine whether to proceed with development and production."],[0,"(l) Development.—The term \"development\" means those activities which take place following discovery of minerals in paying quantities, including geophysical activity, drilling, platform construction, and operation of all onshore support facilities, and which are for the purpose of ultimately producing the minerals discovered."],[0,"(m) Production.—The term \"production\" means those activities which take place after the successful completion of any means for the removal of minerals, including such removal, field operations, transfer of minerals to shore, operation monitoring, maintenance, and work-over drilling."],[0,"(n) Antitrust law.—The term \"antitrust law\" means—"],[1,"(1) the Sherman Act (15 U.S.C. 1 et seq.);"],[1,"(2) the Clayton Act (15 U.S.C. 12 et seq.);"],[1,"(3) the Federal Trade Commission Act (15 U.S.C. 41 et seq.);"],[1,"(4) the Wilson Tariff Act (15 U.S.C. 8 et seq.); or"],[1,"(5) the Act of June 19, 1936, chapter 592 (15 U.S.C. 13, 13a, 13b, and 21a)."],[0,"(o) Fair market value.—The term \"fair market value\" means the value of any mineral (1) computed at a unit price equivalent to the average unit price at which such mineral was sold pursuant to a lease during the period for which any royalty or net profit share is accrued or reserved to the United States pursuant to such lease, or (2) if there were no such sales, or if the Secretary finds that there were an insufficient number of such sales to equitably determine such value, computed at the average unit price at which such mineral was sold pursuant to other leases in the same region of the outer Continental Shelf during such period, or (3) if there were no sales of such mineral from such region during such period, or if the Secretary finds that there are an insufficient number of such sales to equitably determine such value, at an appropriate price determined by the Secretary."],[0,"(p) Major Federal action.—The term \"major Federal action\" means any action or proposal by the Secretary which is subject to the provisions of section 4332(2)(C) of title 42."],[0,"(q) Minerals.—The term \"minerals\" includes oil, gas, sulphur, geopressured-geothermal and associated resources, and all other minerals which are authorized by an Act of Congress to be produced from \"public lands\" as defined in section 1702 of this title; and 3"],[0,"(r) 4 Carbon dioxide stream.—"],[1,"(1) In general.—The term \"carbon dioxide stream\" means carbon dioxide that—"],[2,"(A) has been captured; and"],[2,"(B) consists overwhelmingly of—"],[3,"(i) carbon dioxide plus incidental associated substances derived from the source material or capture process; and"],[3,"(ii) any substances added to the stream for the purpose of enabling or improving the injection process."],[1,"(2) Exclusions.—The term \"carbon dioxide stream\" does not include additional waste or other matter added to the carbon dioxide stream for the purpose of disposal."],[0,"(s) Carbon sequestration.—The term \"carbon sequestration\" means the act of storing carbon dioxide that has been removed from the atmosphere or captured through physical, chemical, or biological processes that can prevent the carbon dioxide from reaching the atmosphere."],[0,"(r) 5 The term \"State\" means—"],[1,"(1) each of the several States;"],[1,"(2) the Commonwealth of Puerto Rico;"],[1,"(3) Guam;"],[1,"(4) American Samoa;"],[1,"(5) the United States Virgin Islands; and"],[1,"(6) the Commonwealth of the Northern Mariana Islands."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/43/1331?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1331. Definitions","tname":"Public Lands","by":{"0":"3","1":"1, 3, 3","2":"passim"}},{"t":"usc","label":"43 U.S.C. § 1333","url":"https://www.law.cornell.edu/uscode/text/43/1333","subs":["(a)(1)","(a)(2)(A)","(a)(3)","(a)","(a)(2)"],"stext":{"head":"§1333. Laws and regulations governing lands","paras":[[0,"(a) Constitution and United States laws; laws of adjacent States; publication of projected State lines; international boundary disputes; restriction on State taxation and jurisdiction"],[0,"(1) Jurisdiction of the united states on the outer continental shelf.—"],[1,"(A) In general.—The Constitution and laws and civil and political jurisdiction of the United States are extended, to the same extent as if the outer Continental Shelf were an area of exclusive Federal jurisdiction located within a State, to—"],[2,"(i) the subsoil and seabed of the outer Continental Shelf;"],[2,"(ii) all artificial islands on the outer Continental Shelf;"],[2,"(iii) installations and other devices permanently or temporarily attached to the seabed, which may be erected thereon for the purpose of exploring for, developing, or producing resources, including non-mineral energy resources; or"],[2,"(iv) any such installation or other device (other than a ship or vessel) for the purpose of transporting or transmitting such resources."],[1,"(B) Leases issued exclusively under this act.—Mineral or energy leases on the outer Continental Shelf shall be maintained or issued only under the provisions of this subchapter."],[0,"(2)(A) To the extent that they are applicable and not inconsistent with this subchapter or with other Federal laws and regulations of the Secretary now in effect or hereafter adopted, the civil and criminal laws of each adjacent State, now in effect or hereafter adopted, amended, or repealed are declared to be the law of the United States for that portion of the subsoil and seabed of the outer Continental Shelf, and artificial islands and fixed structures erected thereon, which would be within the area of the State if its boundaries were extended seaward to the outer margin of the outer Continental Shelf, and the President shall determine and publish in the Federal Register such projected lines extending seaward and defining each such area. All of such applicable laws shall be administered and enforced by the appropriate officers and courts of the United States. State taxation laws shall not apply to the outer Continental Shelf."],[0,"(B) Within one year after September 18, 1978, the President shall establish procedures for setting 1 any outstanding international boundary dispute respecting the outer Continental Shelf."],[0,"(3) The provisions of this section for adoption of State law as the law of the United States shall never be interpreted as a basis for claiming any interest in or jurisdiction on behalf of any State for any purpose over the seabed and subsoil of the outer Continental Shelf, or the property and natural resources thereof or the revenues therefrom."],[0,"(b) Longshore and Harbor Workers' Compensation Act applicable; definitions"],[0,"With respect to disability or death of an employee resulting from any injury occurring as the result of operations conducted on the outer Continental Shelf for the purpose of exploring for, developing, removing, or transporting by pipeline the natural resources, or involving rights to the natural resources, of the subsoil and seabed of the outer Continental Shelf, compensation shall be payable under the provisions of the Longshore and Harbor Workers' Compensation Act [33 U.S.C. 901 et seq.]. For the purposes of the extension of the provisions of the Longshore and Harbor Workers' Compensation Act under this section—"],[1,"(1) the term \"employee\" does not include a master or member of a crew of any vessel, or an officer or employee of the United States or any agency thereof or of any State or foreign government, or of any political subdivision thereof;"],[1,"(2) the term \"employer\" means an employer any of whose employees are employed in such operations; and"],[1,"(3) the term \"United States\" when used in a geographical sense includes the outer Continental Shelf and artificial islands and fixed structures thereon."],[0,"(c) National Labor Relations Act applicable"],[0,"For the purposes of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], any unfair labor practice, as defined in such Act, occurring upon any artificial island, installation, or other device referred to in subsection (a) of this section shall be deemed to have occurred within the judicial district of the State, the laws of which apply to such artificial island, installation, or other device pursuant to such subsection, except that until the President determines the areas within which such State laws are applicable, the judicial district shall be that of the State nearest the place of location of such artificial island, installation, or other device."],[0,"(d) Coast Guard regulations; marking of artificial islands, installations, and other devices; failure of owner suitably to mark according to regulations"],[0,"(1) The Secretary of the Department in which the Coast Guard is operating shall have authority to promulgate and enforce such reasonable regulations with respect to lights and other warning devices, safety equipment, and other matters relating to the promotion of safety of life and property on the artificial islands, installations, and other devices referred to in subsection (a) or on the waters adjacent thereto, as he may deem necessary."],[0,"(2) The Secretary of the Department in which the Coast Guard is operating may mark for the protection of navigation any artificial island, installation, or other device referred to in subsection (a) whenever the owner has failed suitably to mark such island, installation, or other device in accordance with regulations issued under this subchapter, and the owner shall pay the cost of such marking."],[0,"(e) Authority of Secretary of the Army to prevent obstruction to navigation"],[0,"The authority of the Secretary of the Army to prevent obstruction to navigation in the navigable waters of the United States is extended to the artificial islands, installations, and other devices referred to in subsection (a)."],[0,"(f) Provisions as nonexclusive"],[0,"The specific application by this section of certain provisions of law to the subsoil and seabed of the outer Continental Shelf and the artificial islands, installations, and other devices referred to in subsection (a) or to acts or offenses occurring or committed thereon shall not give rise to any inference that the application to such islands and structures, acts, or offenses of any other provision of law is not intended."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/43/1333?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§1333. Laws and regulations governing lands","tname":"Public Lands","by":{"0":"passim, passim, passim","1":"4, 4, 4, 4, 4"}},{"t":"law","label":"Pub. L. No. 93-627","url":"https://www.govinfo.gov/link/statute/88/2146","by":{"0":"29","1":"14","2":"8"}},{"t":"law","label":"Pub. L. No. 95-372","url":"https://www.govinfo.gov/link/statute/92/635","by":{"0":"29","2":"10"}},{"t":"reg","label":"29 C.F.R. § 785.19","url":"https://www.ecfr.gov/current/title-29/section-785.19","by":{"0":"32"}},{"t":"reg","label":"29 C.F.R. § 785.22","url":"https://www.ecfr.gov/current/title-29/section-785.22","by":{"0":"48"}},{"t":"reg","label":"29 C.F.R. § 785.23","url":"https://www.ecfr.gov/current/title-29/section-785.23","by":{"0":"8, 31","1":"32"}},{"t":"reg","label":"Exec. Order No. 13,795, 82 Fed. Reg. 20,815","url":"https://www.govinfo.gov/link/fr/82/20815","by":{"0":"48"}},{"t":"case","label":"Air Terminal Servs., Inc. v. Rentzel","cite":"81 F. Supp. 611","y":1949,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp./81/611/","by":{"1":"25"}},{"t":"case","label":"American Elec. Power Co. v. Connecticut","cite":"564 U.S. 410","y":2011,"id":"2010/10-174","sc":1,"sum":"The Court held that held the Clean Air Act bars suits by governmental bodies and private parties seeking to curb emissions from utilities via the federal common law.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Blackburn v. United States","cite":"100 F.3d 1426","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/100/1426/","by":{"1":"25"}},{"t":"case","label":"Cheyenne-Arapaho Tribes of Oklahoma v. Oklahoma","cite":"618 F.2d 665","y":1980,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/618/665/","by":{"1":"26"}},{"t":"case","label":"Department of the Treasury v. FLRA","cite":"494 U.S. 922","y":1990,"id":"1989/88-2123","sc":1,"sum":"The FLRA erred in holding that the Act requires the IRS to bargain over the NTEU proposal.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11, 20"}},{"t":"case","label":"Ervin v. OS Rest. Servs., Inc.","cite":"632 F.3d 971","y":2011,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/632/971/","by":{"1":"29"}},{"t":"case","label":"Leocal v. Ashcroft","cite":"543 U.S. 1","y":2004,"id":"2004/03-583","sc":1,"sum":"The Court held that state DUI offenses, except when involving purposeful intent, are accidental and not crimes of violence under federal law. Le therefore did not commit an aggravated felony for which he could be deported.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Mutual Pharm. Co. v. Bartlett","cite":"570 U.S. 472","y":2013,"id":"2012/12-142","sc":1,"sum":"The Court found that federal law preempts state law design-defect claims.","sumSrc":"Oyez","by":{"1":"29, 30"}},{"t":"case","label":"Pacific Coast Dairy v. Department of Agric. of Cal.","cite":"318 U.S. 285","y":1943,"id":"scdb/1942-096","sc":1,"op":1,"sum":"1. The State of California is precluded by the Federal Constitution (Art. I, § 8, cl. 17, and the supremacy clause) from revoking the license of a milk dealer for selling milk to the War Department at less than the minimum price fixed by state law, where the sales and deliveries were made on Moffett Field, which is subject to the exclusive jurisdiction of the United States. Penn Dairies v. Milk Control Comm'n, ante, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"12"}},{"t":"case","label":"Samantar v. Yousuf","cite":"560 U.S. 305","y":2010,"id":"2009/08-1555","sc":1,"sum":"The Court held that the Foreign Sovereign Immunities Act does not extend to an individual acting in his official capacity on behalf of the foreign state.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Tetra Techs., Inc. v. Continental Ins. Co.","cite":"814 F.3d 733","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/814/733/","by":{"1":"19"}},{"t":"case","label":"Williams v. United States","cite":"327 U.S. 711","y":1946,"id":"scdb/1945-043","sc":1,"sum":"that the Assimilative Crimes Act did not make the Arizona law applicable to the case of a married white man who, within the Colorado River Indian Reservation in Arizona, had sexual intercourse with an unmarried Indian girl then over 16 but under 18 years of age. P. 7.18.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13, 24, 27"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"1":"30"}},{"t":"usc","label":"42 U.S.C. § 7401","url":"https://www.law.cornell.edu/uscode/text/42/7401","stext":{"head":"§7401. Congressional findings and declaration of purpose","paras":[[0,"(a) Findings"],[0,"The Congress finds—"],[1,"(1) that the predominant part of the Nation's population is located in its rapidly expanding metropolitan and other urban areas, which generally cross the boundary lines of local jurisdictions and often extend into two or more States;"],[1,"(2) that the growth in the amount and complexity of air pollution brought about by urbanization, industrial development, and the increasing use of motor vehicles, has resulted in mounting dangers to the public health and welfare, including injury to agricultural crops and livestock, damage to and the deterioration of property, and hazards to air and ground transportation;"],[1,"(3) that air pollution prevention (that is, the reduction or elimination, through any measures, of the amount of pollutants produced or created at the source) and air pollution control at its source is the primary responsibility of States and local governments; and"],[1,"(4) that Federal financial assistance and leadership is essential for the development of cooperative Federal, State, regional, and local programs to prevent and control air pollution."],[0,"(b) Declaration"],[0,"The purposes of this subchapter are—"],[1,"(1) to protect and enhance the quality of the Nation's air resources so as to promote the public health and welfare and the productive capacity of its population;"],[1,"(2) to initiate and accelerate a national research and development program to achieve the prevention and control of air pollution;"],[1,"(3) to provide technical and financial assistance to State and local governments in connection with the development and execution of their air pollution prevention and control programs; and"],[1,"(4) to encourage and assist the development and operation of regional air pollution prevention and control programs."],[0,"(c) Pollution prevention"],[0,"A primary goal of this chapter is to encourage or otherwise promote reasonable Federal, State, and local governmental actions, consistent with the provisions of this chapter, for pollution prevention."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7401?type=usc&year=mostrecent&link-type=html"},"head":"§7401. Congressional findings and declaration of purpose","tname":"The Public Health and Welfare","by":{"1":"31","2":"53"}},{"t":"usc","label":"42 U.S.C. § 7416","url":"https://www.law.cornell.edu/uscode/text/42/7416","by":{"1":"32"}},{"t":"usc","label":"42 U.S.C. § 7627","url":"https://www.law.cornell.edu/uscode/text/42/7627","subs":["(a)","(a)(1)","(a)(3)"],"stext":{"head":"§7627. Air pollution from Outer Continental Shelf activities","paras":[[0,"(a) Applicable requirements for certain areas"],[0,"(1) In general"],[1,"Not later than 12 months after November 15, 1990, following consultation with the Secretary of the Interior and the Commandant of the United States Coast Guard, the Administrator, by rule, shall establish requirements to control air pollution from Outer Continental Shelf sources located offshore of the States along the Pacific, Arctic and Atlantic Coasts (other than Outer Continental Shelf sources located offshore of the North Slope Borough of the State of Alaska), and along the United States Gulf Coast off the State of Florida eastward of longitude 87 degrees and 30 minutes (\"OCS sources\") to attain and maintain Federal and State ambient air quality standards and to comply with the provisions of part C of subchapter I. For such sources located within 25 miles of the seaward boundary of such States, such requirements shall be the same as would be applicable if the source were located in the corresponding onshore area, and shall include, but not be limited to, State and local requirements for emission controls, emission limitations, offsets, permitting, monitoring, testing, and reporting. New OCS sources shall comply with such requirements on the date of promulgation and existing OCS sources shall comply on the date 24 months thereafter. The Administrator shall update such requirements as necessary to maintain consistency with onshore regulations and this chapter. The authority of this subsection shall supersede section 5(a)(8) of the Outer Continental Shelf Lands Act [43 U.S.C. 1334(a)(8)] but shall not repeal or modify any other Federal, State, or local authorities with respect to air quality. Each requirement established under this section shall be treated, for purposes of sections 7413, 7414, 7416, 7420, and 7604 of this title, as a standard under section 7411 of this title and a violation of any such requirement shall be considered a violation of section 7411(e) of this title."],[0,"(2) Exemptions"],[1,"The Administrator may exempt an OCS source from a specific requirement in effect under regulations under this subsection if the Administrator finds that compliance with a pollution control technology requirement is technically infeasible or will cause an unreasonable threat to health and safety. The Administrator shall make written findings explaining the basis of any exemption issued pursuant to this subsection and shall impose another requirement equal to or as close in stringency to the original requirement as possible. The Administrator shall ensure that any increase in emissions due to the granting of an exemption is offset by reductions in actual emissions, not otherwise required by this chapter, from the same source or other sources in the area or in the corresponding onshore area. The Administrator shall establish procedures to provide for public notice and comment on exemptions proposed pursuant to this subsection."],[0,"(3) State procedures"],[1,"Each State adjacent to an OCS source included under this subsection may promulgate and submit to the Administrator regulations for implementing and enforcing the requirements of this subsection. If the Administrator finds that the State regulations are adequate, the Administrator shall delegate to that State any authority the Administrator has under this chapter to implement and enforce such requirements. Nothing in this subsection shall prohibit the Administrator from enforcing any requirement of this section."],[0,"(4) Definitions"],[1,"For purposes of subsections (a) and (b)—"],[0,"(A) Outer Continental Shelf"],[2,"The term \"Outer Continental Shelf\" has the meaning provided by section 2 of the Outer Continental Shelf Lands Act (43 U.S.C. 1331)."],[0,"(B) Corresponding onshore area"],[2,"The term \"corresponding onshore area\" means, with respect to any OCS source, the onshore attainment or nonattainment area that is closest to the source, unless the Administrator determines that another area with more stringent requirements with respect to the control and abatement of air pollution may reasonably be expected to be affected by such emissions. Such determination shall be based on the potential for air pollutants from the OCS source to reach the other onshore area and the potential of such air pollutants to affect the efforts of the other onshore area to attain or maintain any Federal or State ambient air quality standard or to comply with the provisions of part C of subchapter I."],[0,"(C) Outer Continental Shelf source"],[2,"The terms \"Outer Continental Shelf source\" and \"OCS source\" include any equipment, activity, or facility which—"],[3,"(i) emits or has the potential to emit any air pollutant,"],[3,"(ii) is regulated or authorized under the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.], and"],[3,"(iii) is located on the Outer Continental Shelf or in or on waters above the Outer Continental Shelf."],[2,"Such activities include, but are not limited to, platform and drill ship exploration, construction, development, production, processing, and transportation. For purposes of this subsection, emissions from any vessel servicing or associated with an OCS source, including emissions while at the OCS source or en route to or from the OCS source within 25 miles of the OCS source, shall be considered direct emissions from the OCS source."],[0,"(D) New and existing OCS sources"],[2,"The term \"new OCS source\" means an OCS source which is a new source within the meaning of section 7411(a) of this title. The term \"existing OCS source\" means any OCS source other than a new OCS source."],[0,"(b) Requirements for other offshore areas"],[0,"For portions of the United States Outer Continental Shelf that are adjacent to the States not covered by subsection (a) which are Texas, Louisiana, Mississippi, and Alabama or are adjacent to the North Slope Borough of the State of Alaska, the Secretary shall consult with the Administrator to assure coordination of air pollution control regulation for Outer Continental Shelf emissions and emissions in adjacent onshore areas. Concurrently with this obligation, the Secretary shall complete within 3 years of November 15, 1990, a research study examining the impacts of emissions from Outer Continental Shelf activities in such areas that fail to meet the national ambient air quality standards for either ozone or nitrogen dioxide. Based on the results of this study, the Secretary shall consult with the Administrator and determine if any additional actions are necessary. There are authorized to be appropriated such sums as may be necessary to provide funding for the study required under this section."],[0,"(c) Coastal waters"],[0,"(1) The study report of section 7412(n) 1 of this title shall apply to the coastal waters of the United States to the same extent and in the same manner as such requirements apply to the Great Lakes, the Chesapeake Bay, and their tributary waters."],[0,"(2) The regulatory requirements of section 7412(n) 1 of this title shall apply to the coastal waters of the States which are subject to subsection (a) of this section, to the same extent and in the same manner as such requirements apply to the Great Lakes, the Chesapeake Bay, and their tributary waters."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7627?type=usc&year=mostrecent&link-type=html"},"head":"§7627. Air pollution from Outer Continental Shelf activities","tname":"The Public Health and Welfare","by":{"1":"32","2":"53, 54, 53, 54"}},{"t":"usc","label":"40 U.S.C. § 3701","url":"https://www.law.cornell.edu/uscode/text/40/3701","by":{"1":"31, 32"}},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","stext":{"head":"§201. Short title","paras":[[0,"This chapter may be cited as the \"Fair Labor Standards Act of 1938\"."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/201?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§201. Short title","tname":"Labor","by":{"1":"5","2":"passim"}},{"t":"usc","label":"29 U.S.C. § 206","url":"https://www.law.cornell.edu/uscode/text/29/206","subs":["(a)(1)"],"stext":{"head":"§206. Minimum wage","paras":[[0,"(a) Employees engaged in commerce; home workers in Puerto Rico and Virgin Islands; employees in American Samoa; seamen on American vessels; agricultural employees"],[0,"Every employer shall pay to each of his employees who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, wages at the following rates:"],[1,"(1) except as otherwise provided in this section, not less than—"],[2,"(A) $5.85 an hour, beginning on the 60th day after May 25, 2007;"],[2,"(B) $6.55 an hour, beginning 12 months after that 60th day; and"],[2,"(C) $7.25 an hour, beginning 24 months after that 60th day;"],[1,"(2) if such employee is a home worker in Puerto Rico or the Virgin Islands, not less than the minimum piece rate prescribed by regulation or order; or, if no such minimum piece rate is in effect, any piece rate adopted by such employer which shall yield, to the proportion or class of employees prescribed by regulation or order, not less than the applicable minimum hourly wage rate. Such minimum piece rates or employer piece rates shall be commensurate with, and shall be paid in lieu of, the minimum hourly wage rate applicable under the provisions of this section. The Administrator, or his authorized representative, shall have power to make such regulations or orders as are necessary or appropriate to carry out any of the provisions of this paragraph, including the power without limiting the generality of the foregoing, to define any operation or occupation which is performed by such home work employees in Puerto Rico or the Virgin Islands; to establish minimum piece rates for any operation or occupation so defined; to prescribe the method and procedure for ascertaining and promulgating minimum piece rates; to prescribe standards for employer piece rates, including the proportion or class of employees who shall receive not less than the minimum hourly wage rate; to define the term \"home worker\"; and to prescribe the conditions under which employers, agents, contractors, and subcontractors shall cause goods to be produced by home workers;"],[1,"(3) if such employee is employed as a seaman on an American vessel, not less than the rate which will provide to the employee, for the period covered by the wage payment, wages equal to compensation at the hourly rate prescribed by paragraph (1) of this subsection for all hours during such period when he was actually on duty (including periods aboard ship when the employee was on watch or was, at the direction of a superior officer, performing work or standing by, but not including off-duty periods which are provided pursuant to the employment agreement); or"],[1,"(4) if such employee is employed in agriculture, not less than the minimum wage rate in effect under paragraph (1) after December 31, 1977."],[0,"(b) Additional applicability to employees pursuant to subsequent amendatory provisions"],[0,"Every employer shall pay to each of his employees (other than an employee to whom subsection (a)(5) 1 applies) who in any workweek is engaged in commerce or in the production of goods for commerce, or is employed in an enterprise engaged in commerce or in the production of goods for commerce, and who in such workweek is brought within the purview of this section by the amendments made to this chapter by the Fair Labor Standards Amendments of 1966, title IX of the Education Amendments of 1972 [20 U.S.C. 1681 et seq.], or the Fair Labor Standards Amendments of 1974, wages at the following rate: Effective after December 31, 1977, not less than the minimum wage rate in effect under subsection (a)(1)."],[0,"(c) Repealed. Pub. L. 104–188, [title II], §2104(c), Aug. 20, 1996, 110 Stat. 1929"],[0,"(d) Prohibition of sex discrimination"],[0,"(1) No employer having employees subject to any provisions of this section shall discriminate, within any establishment in which such employees are employed, between employees on the basis of sex by paying wages to employees in such establishment at a rate less than the rate at which he pays wages to employees of the opposite sex in such establishment for equal work on jobs the performance of which requires equal skill, effort, and responsibility, and which are performed under similar working conditions, except where such payment is made pursuant to (i) a seniority system; (ii) a merit system; (iii) a system which measures earnings by quantity or quality of production; or (iv) a differential based on any other factor other than sex: Provided, That an employer who is paying a wage rate differential in violation of this subsection shall not, in order to comply with the provisions of this subsection, reduce the wage rate of any employee."],[0,"(2) No labor organization, or its agents, representing employees of an employer having employees subject to any provisions of this section shall cause or attempt to cause such an employer to discriminate against an employee in violation of paragraph (1) of this subsection."],[0,"(3) For purposes of administration and enforcement, any amounts owing to any employee which have been withheld in violation of this subsection shall be deemed to be unpaid minimum wages or unpaid overtime compensation under this chapter."],[0,"(4) As used in this subsection, the term \"labor organization\" means any organization of any kind, or any agency or employee representation committee or plan, in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours of employment, or conditions of work."],[0,"(e) Employees of employers providing contract services to United States"],[0,"(1) Notwithstanding the provisions of section 213 of this title (except subsections (a)(1) and (f) thereof), every employer providing any contract services (other than linen supply services) under a contract with the United States or any subcontract thereunder shall pay to each of his employees whose rate of pay is not governed by chapter 67 of title 41 or to whom subsection (a)(1) of this section is not applicable, wages at rates not less than the rates provided for in subsection (b) of this section."],[0,"(2) Notwithstanding the provisions of section 213 of this title (except subsections (a)(1) and (f) thereof) and the provisions of chapter 67 of title 41, every employer in an establishment providing linen supply services to the United States under a contract with the United States or any subcontract thereunder shall pay to each of his employees in such establishment wages at rates not less than those prescribed in subsection (b), except that if more than 50 per centum of the gross annual dollar volume of sales made or business done by such establishment is derived from providing such linen supply services under any such contracts or subcontracts, such employer shall pay to each of his employees in such establishment wages at rates not less than those prescribed in subsection (a)(1) of this section."],[0,"(f) Employees in domestic service"],[0,"Any employee—"],[1,"(1) who in any workweek is employed in domestic service in a household shall be paid wages at a rate not less than the wage rate in effect under subsection (b) unless such employee's compensation for such service would not because of section 209(a)(6) of the Social Security Act [42 U.S.C. 409(a)(6)] constitute wages for the purposes of title II of such Act [42 U.S.C. 401 et seq.], or"],[1,"(2) who in any workweek—"],[2,"(A) is employed in domestic service in one or more households, and"],[2,"(B) is so employed for more than 8 hours in the aggregate,"],[0,"shall be paid wages for such employment in such workweek at a rate not less than the wage rate in effect under subsection (b)."],[0,"(g) Newly hired employees who are less than 20 years old"],[0,"(1) In lieu of the rate prescribed by subsection (a)(1), any employer may pay any employee of such employer, during the first 90 consecutive calendar days after such employee is initially employed by such employer, a wage which is not less than $4.25 an hour."],[0,"(2) In lieu of the rate prescribed by subsection (a)(1), the Governor of Puerto Rico, subject to the approval of the Financial Oversight and Management Board established pursuant to section 2121 of title 48, may designate a time period not to exceed four years during which employers in Puerto Rico may pay employees who are initially employed after June 30, 2016, a wage which is not less than the wage described in paragraph (1). Notwithstanding the time period designated, such wage shall not continue in effect after such Board terminates in accordance with section 2149 of title 48."],[0,"(3) No employer may take any action to displace employees (including partial displacements such as reduction in hours, wages, or employment benefits) for purposes of hiring individuals at the wage authorized in paragraph (1) or (2)."],[0,"(4) Any employer who violates this subsection shall be considered to have violated section 215(a)(3) of this title."],[0,"(5) This subsection shall only apply to an employee who has not attained the age of 20 years, except in the case of the wage applicable in Puerto Rico, 25 years, until such time as the Board described in paragraph (2) terminates in accordance with section 2149 of title 48."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/206?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§206. Minimum wage","tname":"Labor","by":{"1":"31"}},{"t":"usc","label":"33 U.S.C. § 901","url":"https://www.law.cornell.edu/uscode/text/33/901","stext":{"head":"§901. Short title","paras":[[0,"This chapter may be cited as \"Longshore and Harbor Workers' Compensation Act.\""]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/901?type=usc&year=mostrecent&link-type=html"},"head":"§901. Short title","tname":"Navigation and Navigable Waters","by":{"1":"31","2":"42, 48"}},{"t":"usc","label":"43 U.S.C. § 1332","url":"https://www.law.cornell.edu/uscode/text/43/1332","subs":["(1)"],"by":{"1":"4"}},{"t":"usc","label":"43 U.S.C. § 1334","url":"https://www.law.cornell.edu/uscode/text/43/1334","stext":{"head":"§1334. Administration of leasing","paras":[[0,"(a) Rules and regulations; amendment; cooperation with State agencies; subject matter and scope of regulations"],[0,"The Secretary shall administer the provisions of this subchapter relating to the leasing of the outer Continental Shelf, and shall prescribe such rules and regulations as may be necessary to carry out such provisions. The Secretary may at any time prescribe and amend such rules and regulations as he determines to be necessary and proper in order to provide for the prevention of waste and conservation of the natural resources of the outer Continental Shelf, and the protection of correlative rights therein, and, notwithstanding any other provisions herein, such rules and regulations shall, as of their effective date, apply to all operations conducted under a lease issued or maintained under the provisions of this subchapter. In the enforcement of safety, environmental, and conservation laws and regulations, the Secretary shall cooperate with the relevant departments and agencies of the Federal Government and of the affected States. In the formulation and promulgation of regulations, the Secretary shall request and give due consideration to the views of the Attorney General with respect to matters which may affect competition. In considering any regulations and in preparing any such views, the Attorney General shall consult with the Federal Trade Commission. The regulations prescribed by the Secretary under this subsection shall include, but not be limited to, provisions—"],[1,"(1) for the suspension or temporary prohibition of any operation or activity, including production, pursuant to any lease or permit (A) at the request of a lessee, in the national interest, to facilitate proper development of a lease or to allow for the construction or negotiation for use of transportation facilities, or (B) if there is a threat of serious, irreparable, or immediate harm or damage to life (including fish and other aquatic life), to property, to any mineral deposits (in areas leased or not leased), or to the marine, coastal, or human environment, and for the extension of any permit or lease affected by suspension or prohibition under clause (A) or (B) by a period equivalent to the period of such suspension or prohibition, except that no permit or lease shall be so extended when such suspension or prohibition is the result of gross negligence or willful violation of such lease or permit, or of regulations issued with respect to such lease or permit;"],[1,"(2) with respect to cancellation of any lease or permit—"],[2,"(A) that such cancellation may occur at any time, if the Secretary determines, after a hearing, that—"],[3,"(i) continued activity pursuant to such lease or permit would probably cause serious harm or damage to life (including fish and other aquatic life), to property, to any mineral (in areas leased or not leased), to the national security or defense, or to the marine, coastal, or human environment;"],[3,"(ii) the threat of harm or damage will not disappear or decrease to an acceptable extent within a reasonable period of time; and"],[3,"(iii) the advantages of cancellation outweigh the advantages of continuing such lease or permit force;"],[2,"(B) that such cancellation shall not occur unless and until operations under such lease or permit shall have been under suspension, or temporary prohibition, by the Secretary, with due extension of any lease or permit term continuously for a period of five years, or for a lesser period upon request of the lessee;"],[2,"(C) that such cancellation shall entitle the lessee to receive such compensation as he shows to the Secretary as being equal to the lesser of (i) the fair value of the canceled rights as of the date of cancellation, taking account of both anticipated revenues from the lease and anticipated costs, including costs of compliance with all applicable regulations and operating orders, liability for cleanup costs or damages, or both, in the case of an oilspill, and all other costs reasonably anticipated on the lease, or (ii) the excess, if any, over the lessee's revenues, from the lease (plus interest thereon from the date of receipt to date of reimbursement) of all consideration paid for the lease and all direct expenditures made by the lessee after the date of issuance of such lease and in connection with exploration or development, or both, pursuant to the lease (plus interest on such consideration and such expenditures from date of payment to date of reimbursement), except that (I) with respect to leases issued before September 18, 1978, such compensation shall be equal to the amount specified in clause (i) of this subparagraph; and (II) in the case of joint leases which are canceled due to the failure of one or more partners to exercise due diligence, the innocent parties shall have the right to seek damages for such loss from the responsible party or parties and the right to acquire the interests of the negligent party or parties and be issued the lease in question;"],[1,"(3) for the assignment or relinquishment of a lease;"],[1,"(4) for unitization, pooling, and drilling agreements;"],[1,"(5) for the subsurface storage of oil and gas from any source other than by the Federal Government;"],[1,"(6) for drilling or easements necessary for exploration, development, and production;"],[1,"(7) for the prompt and efficient exploration and development of a lease area; and"],[1,"(8) for compliance with the national ambient air quality standards pursuant to the Clean Air Act (42 U.S.C. 7401 et seq.), to the extent that activities authorized under this subchapter significantly affect the air quality of any State."],[0,"(b) Compliance with regulations as condition for issuance, continuation, assignment, or other transfer of leases"],[0,"The issuance and continuance in effect of any lease, or of any assignment or other transfer of any lease, under the provisions of this subchapter shall be conditioned upon compliance with regulations issued under this subchapter."],[0,"(c) Cancellation of nonproducing lease"],[0,"Whenever the owner of a nonproducing lease fails to comply with any of the provisions of this subchapter, or of the lease, or of the regulations issued under this subchapter, such lease may be canceled by the Secretary, subject to the right of judicial review as provided in this subchapter, if such default continues for the period of thirty days after mailing of notice by registered letter to the lease owner at his record post office address."],[0,"(d) Cancellation of producing lease"],[0,"Whenever the owner of any producing lease fails to comply with any of the provisions of this subchapter, of the lease, or of the regulations issued under this subchapter, such lease may be forfeited and canceled by an appropriate proceeding in any United States district court having jurisdiction under the provisions of this subchapter."],[0,"(e) Pipeline rights-of-way; forfeiture of grant"],[0,"Rights-of-way through the submerged lands of the outer Continental Shelf, whether or not such lands are included in a lease maintained or issued pursuant to this subchapter, may be granted by the Secretary for pipeline purposes for the transportation of oil, natural gas, sulphur, or other minerals, or under such regulations and upon such conditions as may be prescribed by the Secretary, or where appropriate the Secretary of Transportation, including (as provided in section 1347(b) of this title) assuring maximum environmental protection by utilization of the best available and safest technologies, including the safest practices for pipeline burial and upon the express condition that oil or gas pipelines shall transport or purchase without discrimination, oil or natural gas produced from submerged lands or outer Continental Shelf lands in the vicinity of the pipelines in such proportionate amounts as the Federal Energy Regulatory Commission, in consultation with the Secretary of Energy, may, after a full hearing with due notice thereof to the interested parties, determine to be reasonable, taking into account, among other things, conservation and the prevention of waste. Failure to comply with the provisions of this section or the regulations and conditions prescribed under this section shall be grounds for forfeiture of the grant in an appropriate judicial proceeding instituted by the United States in any United States district court having jurisdiction under the provisions of this subchapter."],[0,"(f) Competitive principles governing pipeline operation"],[0,"(1) Except as provided in paragraph (2), every permit, license, easement, right-of-way, or other grant of authority for the transportation by pipeline on or across the outer Continental Shelf of oil or gas shall require that the pipeline be operated in accordance with the following competitive principles:"],[1,"(A) The pipeline must provide open and nondiscriminatory access to both owner and nonowner shippers."],[1,"(B) Upon the specific request of one or more owner or nonowner shippers able to provide a guaranteed level of throughput, and on the condition that the shipper or shippers requesting such expansion shall be responsible for bearing their proportionate share of the costs and risks related thereto, the Federal Energy Regulatory Commission may, upon finding, after a full hearing with due notice thereof to the interested parties, that such expansion is within technological limits and economic feasibility, order a subsequent expansion of throughput capacity of any pipeline for which the permit, license, easement, right-of-way, or other grant of authority is approved or issued after September 18, 1978. This subparapraph 1 shall not apply to any such grant of authority approved or issued for the Gulf of Mexico or the Santa Barbara Channel."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/43/1334?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1334. Administration of leasing","tname":"Public Lands","by":{"1":"3"}},{"t":"usc","label":"43 U.S.C. § 1347","url":"https://www.law.cornell.edu/uscode/text/43/1347","by":{"1":"31"}},{"t":"usc","label":"42 U.S.C. § 6901","url":"https://www.law.cornell.edu/uscode/text/42/6901","stext":{"head":"§6901. Congressional findings","paras":[[0,"(a) Solid waste"],[0,"The Congress finds with respect to solid waste—"],[1,"(1) that the continuing technological progress and improvement in methods of manufacture, packaging, and marketing of consumer products has resulted in an ever-mounting increase, and in a change in the characteristics, of the mass material discarded by the purchaser of such products;"],[1,"(2) that the economic and population growth of our Nation, and the improvements in the standard of living enjoyed by our population, have required increased industrial production to meet our needs, and have made necessary the demolition of old buildings, the construction of new buildings, and the provision of highways and other avenues of transportation, which, together with related industrial, commercial, and agricultural operations, have resulted in a rising tide of scrap, discarded, and waste materials;"],[1,"(3) that the continuing concentration of our population in expanding metropolitan and other urban areas has presented these communities with serious financial, management, intergovernmental, and technical problems in the disposal of solid wastes resulting from the industrial, commercial, domestic, and other activities carried on in such areas;"],[1,"(4) that while the collection and disposal of solid wastes should continue to be primarily the function of State, regional, and local agencies, the problems of waste disposal as set forth above have become a matter national in scope and in concern and necessitate Federal action through financial and technical assistance and leadership in the development, demonstration, and application of new and improved methods and processes to reduce the amount of waste and unsalvageable materials and to provide for proper and economical solid waste disposal practices."],[0,"(b) Environment and health"],[0,"The Congress finds with respect to the environment and health, that—"],[1,"(1) although land is too valuable a national resource to be needlessly polluted by discarded materials, most solid waste is disposed of on land in open dumps and sanitary landfills;"],[1,"(2) disposal of solid waste and hazardous waste in or on the land without careful planning and management can present a danger to human health and the environment;"],[1,"(3) as a result of the Clean Air Act [42 U.S.C. 7401 et seq.], the Water Pollution Control Act [33 U.S.C. 1251 et seq.], and other Federal and State laws respecting public health and the environment, greater amounts of solid waste (in the form of sludge and other pollution treatment residues) have been created. Similarly, inadequate and environmentally unsound practices for the disposal or use of solid waste have created greater amounts of air and water pollution and other problems for the environment and for health;"],[1,"(4) open dumping is particularly harmful to health, contaminates drinking water from underground and surface supplies, and pollutes the air and the land;"],[1,"(5) the placement of inadequate controls on hazardous waste management will result in substantial risks to human health and the environment;"],[1,"(6) if hazardous waste management is improperly performed in the first instance, corrective action is likely to be expensive, complex, and time consuming;"],[1,"(7) certain classes of land disposal facilities are not capable of assuring long-term containment of certain hazardous wastes, and to avoid substantial risk to human health and the environment, reliance on land disposal should be minimized or eliminated, and land disposal, particularly landfill and surface impoundment, should be the least favored method for managing hazardous wastes; and"],[1,"(8) alternatives to existing methods of land disposal must be developed since many of the cities in the United States will be running out of suitable solid waste disposal sites within five years unless immediate action is taken."],[0,"(c) Materials"],[0,"The Congress finds with respect to materials, that—"],[1,"(1) millions of tons of recoverable material which could be used are needlessly buried each year;"],[1,"(2) methods are available to separate usable materials from solid waste; and"],[1,"(3) the recovery and conservation of such materials can reduce the dependence of the United States on foreign resources and reduce the deficit in its balance of payments."],[0,"(d) Energy"],[0,"The Congress finds with respect to energy, that—"],[1,"(1) solid waste represents a potential source of solid fuel, oil, or gas that can be converted into energy;"],[1,"(2) the need exists to develop alternative energy sources for public and private consumption in order to reduce our dependence on such sources as petroleum products, natural gas, nuclear and hydroelectric generation; and"],[1,"(3) technology exists to produce usable energy from solid waste."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/6901?type=usc&year=mostrecent&link-type=html"},"head":"§6901. Congressional findings","tname":"The Public Health and Welfare","by":{"1":"31","2":"54"}},{"t":"usc","label":"41 U.S.C. § 6701","url":"https://www.law.cornell.edu/uscode/text/41/6701","by":{"1":"31"}},{"t":"usc","label":"43 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/43/1301","stext":{"head":"§1301. Definitions","paras":[[0,"When used in this subchapter and subchapter II—"],[0,"(a) The term \"lands beneath navigable waters\" means—"],[1,"(1) all lands within the boundaries of each of the respective States which are covered by nontidal waters that were navigable under the laws of the United States at the time such State became a member of the Union, or acquired sovereignty over such lands and waters thereafter, up to the ordinary high water mark as heretofore or hereafter modified by accretion, erosion, and reliction;"],[1,"(2) all lands permanently or periodically covered by tidal waters up to but not above the line of mean high tide and seaward to a line three geographical miles distant from the coast line of each such State and to the boundary line of each such State where in any case such boundary as it existed at the time such State became a member of the Union, or as heretofore approved by Congress, extends seaward (or into the Gulf of Mexico) beyond three geographical miles,1 and"],[1,"(3) all filled in, made, or reclaimed lands which formerly were lands beneath navigable waters, as hereinabove defined;"],[0,"(b) The term \"boundaries\" includes the seaward boundaries of a State or its boundaries in the Gulf of Mexico or any of the Great Lakes as they existed at the time such State became a member of the Union, or as heretofore approved by the Congress, or as extended or confirmed pursuant to section 1312 of this title but in no event shall the term \"boundaries\" or the term \"lands beneath navigable waters\" be interpreted as extending from the coast line more than three geographical miles into the Atlantic Ocean or the Pacific Ocean, or more than three marine leagues into the Gulf of Mexico, except that any boundary between a State and the United States under this subchapter or subchapter II which has been or is hereafter fixed by coordinates under a final decree of the United States Supreme Court shall remain immobilized at the coordinates provided under such decree and shall not be ambulatory;"],[0,"(c) The term \"coast line\" means the line of ordinary low water along that portion of the coast which is in direct contact with the open sea and the line marking the seaward limit of inland waters;"],[0,"(d) The terms \"grantees\" and \"lessees\" include (without limiting the generality thereof) all political subdivisions, municipalities, public and private corporations, and other persons holding grants or leases from a State, or from its predecessor sovereign if legally validated, to lands beneath navigable waters if such grants or leases were issued in accordance with the constitution, statutes, and decisions of the courts of the State in which such lands are situated, or of its predecessor sovereign: Provided, however, That nothing herein shall be construed as conferring upon said grantees or lessees any greater rights or interests other than are described herein and in their respective grants from the State, or its predecessor sovereign;"],[0,"(e) The term \"natural resources\" includes, without limiting the generality thereof, oil, gas, and all other minerals, and fish, shrimp, oysters, clams, crabs, lobsters, sponges, kelp, and other marine animal and plant life but does not include water power, or the use of water for the production of power;"],[0,"(f) The term \"lands beneath navigable waters\" does not include the beds of streams in lands now or heretofore constituting a part of the public lands of the United States if such streams were not meandered in connection with the public survey of such lands under the laws of the United States and if the title to the beds of such streams was lawfully patented or conveyed by the United States or any State to any person;"],[0,"(g) The term \"State\" means any State of the Union;"],[0,"(h) The term \"person\" includes, in addition to a natural person, an association, a State, a political subdivision of a State, or a private, public, or municipal corporation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/43/1301?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1301. Definitions","tname":"Public Lands","by":{"1":"2, 3","2":"5"}},{"t":"usc","label":"43 U.S.C. § 1311","url":"https://www.law.cornell.edu/uscode/text/43/1311","by":{"1":"3"}},{"t":"usc","label":"41 U.S.C. § 6501","url":"https://www.law.cornell.edu/uscode/text/41/6501","by":{"1":"27"}},{"t":"usc","label":"18 U.S.C. § 13","url":"https://www.law.cornell.edu/uscode/text/18/13","subs":["(a)"],"stext":{"head":"§13. Laws of States adopted for areas within Federal jurisdiction","paras":[[0,"(a) Whoever within or upon any of the places now existing or hereafter reserved or acquired as provided in section 7 of this title, or on, above, or below any portion of the territorial sea of the United States not within the jurisdiction of any State, Commonwealth, territory, possession, or district is guilty of any act or omission which, although not made punishable by any enactment of Congress, would be punishable if committed or omitted within the jurisdiction of the State, Territory, Possession, or District in which such place is situated, by the laws thereof in force at the time of such act or omission, shall be guilty of a like offense and subject to a like punishment."],[0,"(b)(1) Subject to paragraph (2) and for purposes of subsection (a) of this section, that which may or shall be imposed through judicial or administrative action under the law of a State, territory, possession, or district, for a conviction for operating a motor vehicle under the influence of a drug or alcohol, shall be considered to be a punishment provided by that law. Any limitation on the right or privilege to operate a motor vehicle imposed under this subsection shall apply only to the special maritime and territorial jurisdiction of the United States."],[0,"(2)(A) In addition to any term of imprisonment provided for operating a motor vehicle under the influence of a drug or alcohol imposed under the law of a State, territory, possession, or district, the punishment for such an offense under this section shall include an additional term of imprisonment of not more than 1 year, or if serious bodily injury of a minor is caused, not more than 5 years, or if death of a minor is caused, not more than 10 years, and an additional fine under this title, or both, if—"],[1,"(i) a minor (other than the offender) was present in the motor vehicle when the offense was committed; and"],[1,"(ii) the law of the State, territory, possession, or district in which the offense occurred does not provide an additional term of imprisonment under the circumstances described in clause (i)."],[0,"(B) For the purposes of subparagraph (A), the term \"minor\" means a person less than 18 years of age."],[0,"(c) Whenever any waters of the territorial sea of the United States lie outside the territory of any State, Commonwealth, territory, possession, or district, such waters (including the airspace above and the seabed and subsoil below, and artificial islands and fixed structures erected thereon) shall be deemed, for purposes of subsection (a), to lie within the area of the State, Commonwealth, territory, possession, or district that it would lie within if the boundaries of such State, Commonwealth, territory, possession, or district were extended seaward to the outer limit of the territorial sea of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/13?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§13. Laws of States adopted for areas within Federal jurisdiction","tname":"Crimes and Criminal Procedure","by":{"1":"32","2":"9, 54, 35"}},{"t":"case","label":"Adkins v. Arnold","cite":"235 U.S. 417","y":1914,"id":"scdb/1914-046","sc":1,"sum":"Under § 16 of the Creek Indian Allotment Act of June 30,1902, c. 1323, 32 Stat. 500, only allotments to living members of the tribe in their own right were subjected to restrictions upon alienation. Allotments on behalf of deceased members were left unrestricted. Skelton v. Dill, ante, p. 206.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"Artis v. District of Columbia","cite":"138 S. Ct. 594","y":2018,"id":"2017/16-460","sc":1,"sum":"The Court decided that the tolling provision of 28 U.S.C. § 1367 suspends or “stops the clock” on the limitations period for supplemental state law claims while the underlying case is pending in federal court and for 30 days thereafter, rather than merely providing a 30-day grace period after dismissal for the plaintiff to refile in state court.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"California Fed. Sav. & Loan Ass’n v. Guerra","cite":"479 U.S. 272","y":1987,"id":"1986/85-494","sc":1,"sum":"The judgment is affirmed. 758 F. 2d 390, affirmed. JUSTICE MARSHALL delivered the opinion of the Court with respect to Parts I, II, III-B, III-C, and IV, concluding that § 12945(b)(2) is not pre-empted by Title VII, as amended by the PDA, because it is not inconsistent with the purposes of Title VII nor does it require the doing of an act that is unlawful under Title VII.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"50"}},{"t":"case","label":"Cortez v. Purolator Air Filtration Prods. Co.","cite":"999 P.2d 706","y":2000,"court":"Cal.","url":"https://www.courtlistener.com/c/P.2d/999/706/","by":{"2":"13"}},{"t":"case","label":"Franklin v. Lynch","cite":"233 U.S. 269","y":1914,"id":"scdb/1913-189","sc":1,"sum":"The act of April 2Í, 1904, c. 1402, 33 Stat. 189, 204, removing restrictions on alienation of lands of non-Indian allottees of the Five Civilized Tribes, did not authorize members of the tribes to sell future acquired property.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"27, 28"}},{"t":"case","label":"Harper v. Virginia Dep’t of Taxation","cite":"509 U.S. 86","y":1993,"id":"1992/91-794","sc":1,"sum":"In Davis v. Michigan Dept. of Treasury,489 U. S. 803, this Court invalidated Michigan's practice of taxing retirement benefits paid by the Federal Government while exempting retirement benefits paid by the State or its political subdivisions. Because Michigan conceded that a refund to federal retirees was the appropriate remedy, the Court remanded for entry of judgment against the State. Virginia subsequently …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"8"}},{"t":"case","label":"Harris Tr. & Sav. Bank v. Salomon Smith Barney Inc.","cite":"530 U.S. 238","y":2000,"id":"1999/99-579","sc":1,"sum":"The Court held that Section 502(a)(3)'s authorization to a plan \"participant, beneficiary, or fiduciary\" to bring a civil action for \"appropriate equitable relief\" extends to a suit against a nonfiduciary \"party in interest\" to a prohibited transaction barred by section 406(a). \"We reject,\" wrote Justice Thomas that, \"absent a substantive provision of ERISA expressly imposing a duty upon a nonfiduciary party in interest, the nonfiduciary party may not be held liable under [section 502(a)(3)].\" Justice Thomas concluded that \"[section 502(a)(3)] itself imposes certain duties, and therefore that liability under that provision does not depend on whether ERISA's substantive provisions impose a specific duty on the party being sued.\".","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"Jimenez v. Quarterman","cite":"555 U.S. 113","y":2009,"id":"2008/07-6984","sc":1,"sum":"The Court held that if a state court grants a criminal defendant the right to file an out-of-time direct appeal, the statute of limitations doesn't begin until after the out-of-time appeal is final.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Kasten v. Saint-Gobain Performance Plastics Corp.","cite":"563 U.S. 1","y":2011,"id":"2010/09-834","sc":1,"sum":"The Court held that the Fair Labor Standards Act applies to a complaint, whether oral or written.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Korndobler v. DNC Parks & Resorts at Sequoia","cite":"2015 WL 3797625","y":2015,"court":"E.D. Cal. June 18","ar":1,"by":{"2":"41"}},{"t":"case","label":"Lamie v. United States Tr.","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"sum":"According to Justice Anthony Kennedy's opinion for the Court: \"The statute is awkward, and even ungrammatical; but that does not make it ambiguous on the point at issue.\" The Court ruled that though the Act's deletion of the words \"or to the debtor's attorney\" from the Bankruptcy Code had rendered a sentence grammatically incorrect, the Act should still be interpreted according to the plain meaning of its text, however awkward.","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"Mendoza v. Nordstrom, Inc.","cite":"393 P.3d 375","y":2017,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/393/375/","by":{"2":"12"}},{"t":"case","label":"Offshore Logistics, Inc. v. Tallentire","cite":"477 U.S. 207","y":1986,"id":"1985/85-202","sc":1,"sum":"Neither OCSLA nor DOHSA requires or permits the application of the Louisiana wrongful death statute in this case so as to entitle respondents to recover nonpecuniary damages under that statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6"}},{"t":"case","label":"Pacific Merch. Shipping Ass’n v. Aubry","cite":"918 F.2d 1409","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/918/1409/","sum":"Holding California wage-and- hour laws apply in the Santa Barbara Channel.","sumSrc":"brief:2","by":{"2":"11, 28, 29"}},{"t":"case","label":"Pacific Operators Offshore, LLP v. Valladolid","cite":"565 U.S. 207","y":2012,"id":"2011/10-507","sc":1,"sum":"The Court held that the Outer Continental Shelf Lands Act extends coverage for injuries that occurred as the result of operations conducted on the outer continental shelf to an employee, as long as the employee can establish a substantial connection between the injury and the employer’s extractive operations.","sumSrc":"Oyez","by":{"2":"5, 32, 42"}},{"t":"case","label":"People v. Weeren","cite":"607 P.2d 1279","y":1980,"court":"Cal.","url":"https://www.courtlistener.com/c/P.2d/607/1279/","by":{"2":"3"}},{"t":"case","label":"Spoerle v. Kraft Foods Glob., Inc.","cite":"614 F.3d 427","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/614/427/","sum":"Holding FLSA provision excluding time spent changing clothes as hours worked did not preempt Wisconsin law including that same time as hours worked for purposes of state wage-and-hour law.","sumSrc":"brief:2","by":{"2":"47"}},{"t":"case","label":"Sun Ship, Inc. v. Pennsylvania","cite":"447 U.S. 715","y":1980,"id":"1979/79-343","sc":1,"op":1,"sum":"A State may apply its workers' compensation scheme to landbased injuries that fall within the coverage of the Longshoremen's and Harbor Workers' Compensation Act (Act), as amended in 1972.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"48, 49","3":"17"}},{"t":"case","label":"Tidewater Marine Western, Inc. v. Bradshaw","cite":"927 P.2d 296","y":1996,"court":"Cal.","url":"https://www.courtlistener.com/c/P.2d/927/296/","sum":"Holding California Labor Code applies to federal waters.","sumSrc":"brief:2","by":{"2":"28"}},{"t":"case","label":"Union Texas Petroleum Corp. v. PLT Eng’g, Inc.","cite":"895 F.2d 1043","y":1990,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/895/1043/","by":{"2":"42"}},{"t":"case","label":"United States v. State Tax Comm’n of Missis- sippi","cite":"412 U.S. 363","y":1973,"id":"1972/72-350","sc":1,"op":1,"sum":"1.The Twenty-first Amendment does not empoiver a State to tax or otherwise regulate the importation of distilled spirits into a territory'over which the United States exercises exclusive jurisdiction, Collins v. Yosemite Park & Curry Co., 304 U.'S. 518, regardless of whether some of the liquor may have been consumed off base.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"38, 39, 40","3":"9"}},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 362","y":2000,"id":"1999/98-8384","sc":1,"sum":"In a judgment announced by Justice John Paul Stevens, the Court, with different majorities of Justices for each holding, held that Williams had been deprived of the constitutional right to the effective assistance of counsel and that the Virginia Supreme Court's refusal to set aside the Williams death sentence was a decision that was contrary to or involved an unreasonable application of clearly established federal law, as determined by the Court.","sumSrc":"Oyez","by":{"2":"37"}},{"t":"law","label":"Pub. L. No. 94-559","url":"https://www.govinfo.gov/link/statute/90/2641","by":{"2":"35"}},{"t":"usc","label":"42 U.S.C. § 1988","url":"https://www.law.cornell.edu/uscode/text/42/1988","subs":["(a)"],"by":{"2":"35"}},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","by":{"2":"54"}},{"t":"usc","label":"33 U.S.C. § 1323","url":"https://www.law.cornell.edu/uscode/text/33/1323","by":{"2":"54"}},{"t":"usc","label":"16 U.S.C. § 1451","url":"https://www.law.cornell.edu/uscode/text/16/1451","by":{"2":"10-11"}},{"t":"usc","label":"46 U.S.C. § 30301","url":"https://www.law.cornell.edu/uscode/text/46/30301","by":{"2":"24, 25"}},{"t":"usc","label":"33 U.S.C. § 1501","url":"https://www.law.cornell.edu/uscode/text/33/1501","by":{"2":"8"}},{"t":"law","label":"Pregnancy Discrimination Act, Pub. L. No. 95-555","url":"https://www.govinfo.gov/link/statute/92/2076","by":{"2":"50"}},{"t":"usc","label":"42 U.S.C. § 6961","url":"https://www.law.cornell.edu/uscode/text/42/6961","by":{"2":"54"}},{"t":"usc","label":"42 U.S.C. § 2000h-4","url":"https://www.law.cornell.edu/uscode/text/42/2000h-4","by":{"2":"50"}},{"t":"reg","label":"40 C.F.R. § 55.15","url":"https://www.ecfr.gov/current/title-40/section-55.15","by":{"2":"54"}},{"t":"reg","label":"Establishing a Minimum Wage for Contractors, Notice of Rate Change in Effect as of January 1, 2019, 83 Fed. Reg. 44,906","url":"https://www.govinfo.gov/link/fr/83/44906","by":{"2":"49"}},{"t":"reg","label":"Notice, Oil and Gas Operations in the Submerged Coastal Lands of the Gulf of Mexico, 15 Fed. Reg. 8835","url":"https://www.govinfo.gov/link/fr/15/8835","by":{"2":"4"}},{"t":"reg","label":"Notice, Oil and Gas Operations in Submerged Coastal Lands of Gulf of Mexico, 17 Fed. Reg. 5833","url":"https://www.govinfo.gov/link/fr/17/5833","by":{"2":"4"}},{"t":"reg","label":"Presidential Proclamation No. 2667, 10 Fed. Reg. 12,303","url":"https://www.govinfo.gov/link/fr/10/12303","by":{"2":"4"}},{"t":"case","label":"Decker v. Nw. Envtl. Def., Ctr.","cite":"568 U.S. 597","y":2013,"id":"2012/11-338","sc":1,"sum":"The Court found that based on the Clean Water Act, a permit is not necessary for storm water runoff because it is not associated with industrial activity.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"Evenwel v. Abbott","cite":"136 S. Ct. 1120","y":2016,"id":"2015/14-940","sc":1,"sum":"The Court determined that the “one person, one vote” principle of the Equal Protection Clause allows a state to draw its legislative districts based on total population.","sumSrc":"Oyez","by":{"3":"13"}},{"t":"case","label":"George v. UXB Int'l, Inc.","cite":"1996 WL 241624","y":1996,"court":"N.D. Cal. May 3","by":{"3":"10"}},{"t":"case","label":"Manning v. Gold Belt Falcon, LLC","cite":"681 F. Supp. 2d 574","y":2010,"court":"D.N.J.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/681/574/","by":{"3":"10"}},{"t":"case","label":"Mersnick v. USProtect Corp.","cite":"2006 WL 3734396","y":2006,"court":"N.D. Cal. Dec. 18","by":{"3":"10"}},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"17"}},{"t":"case","label":"United States v. Alexander","cite":"602 F.2d 1228","y":1979,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/602/1228/","by":{"3":"21"}},{"t":"case","label":"Wachovia Bank, N.A. v. Schmidt","cite":"546 U.S. 303","y":2006,"id":"2005/04-1186","sc":1,"sum":"The Court ruled that a national bank is \"located\" in, and therefore a \"citizen\" of, only the state in which its main office is located. Looking to the history of Congress's diversity jurisdiction statutes, the Court concluded that the word \"located\" need not be interpreted to mean any state where a bank has a physical presence.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Yates v. United States","cite":"135 S. Ct. 1074","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"usc","label":"16 U.S.C. § 218","url":"https://www.law.cornell.edu/uscode/text/16/218","by":{"3":"43"}}]};